/* ============================================================
   招式联合系统
   —— 用「成功率」取代硬币拼点；相邻招式的适配度决定后续命中率
   ============================================================ */

/* 招式类型：近战（贴身）/ 远程 / 守御 三类。
   每类给一个三维向量，两招式之间的适配度 = 归一化点积：
   同类 = 1.0，正交（近战↔远程）= 0.0，部分相关 = 0.4~0.7 */
DATA.moveTypes = {
  "拳": { cls:"melee",  vec:[1.00, 0.16, 0.00], glyph:"拳", desc:"最短的距离，最稳的第一步。" },
  "腿": { cls:"melee",  vec:[0.88, 0.36, 0.00], glyph:"腿", desc:"起脚比出拳慢，但势更重。" },
  "剑": { cls:"melee",  vec:[0.95, 0.32, 0.18], glyph:"剑", desc:"恒之剑法为核，守与攻同源。" },
  "刃": { cls:"melee",  vec:[0.62, 0.82, 0.04], glyph:"刃", desc:"匕首出手极短，必须已经贴身。" },
  "枪": { cls:"melee",  vec:[0.70, 0.55, 0.22], glyph:"枪", desc:"贯。越远越重，是近战里最长的一支。" },
  "斧": { cls:"melee",  vec:[0.90, 0.24, 0.20], glyph:"斧", desc:"重压。起手慢，收势更慢。" },
  "弓": { cls:"ranged", vec:[0.04, 0.72, 0.70], glyph:"弓", desc:"远。箭早已在那里，拉弓只是取回来。" },
  "阵": { cls:"ranged", vec:[0.10, 0.42, 0.95], glyph:"阵", desc:"星辰与规则之力，从中距离落下。" },
  "守": { cls:"guard",  vec:[0.18, 0.16, 0.92], glyph:"守", desc:"护盾。拼不赢的时候，先不倒。" },
  "闪": { cls:"guard",  vec:[0.34, 0.42, 0.62], glyph:"闪", desc:"躲闪。让你下一击更稳。" }
};

/* 适配度：对称、同类最高、近战↔远程最低 */
DATA.affinity = (function () {
  const T = DATA.moveTypes;
  const dot = (a, b) => a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
  const norm = (a) => Math.sqrt(dot(a, a));
  const out = {};
  Object.keys(T).forEach((x) => {
    out[x] = {};
    Object.keys(T).forEach((y) => {
      const v = dot(T[x].vec, T[y].vec) / (norm(T[x].vec) * norm(T[y].vec));
      out[x][y] = Math.max(0, Math.min(1, v));
    });
  });
  return out;
})();

