/**
 * 由实力刻度推出一名斗士的战斗数值。
 * 两边共用同一套换算，所以强的一方只是「更可能赢」，不是必胜。
 */
DATA.duelStats = function (d) {
  const pw = d.power || 6;
  return {
    maxHp: Math.round(240 + pw * 26),          /* 强者的血略多，但不夸张 */
    atk: Math.round(9 + pw * 1.5),
    defLevel: Math.round(5 + pw * 1.05),
    speed: Math.round(8 + pw * 0.9)
  };
};


