/* ============================================================
   合并层：把新招式 / 新兵装 / 新类型并入既有结构
   （放在文件最后，保证前面所有定义都已存在）
   ============================================================ */
(function () {
  /* 1. 招式类型：把「术 / 械 / 医」并入 */
  if (DATA.newMoveTypes) {
    Object.keys(DATA.newMoveTypes).forEach(function (k) {
      DATA.moveTypes[k] = DATA.newMoveTypes[k];
    });
  }
  /* 2. 招式：并入（玩家新招式 + 敌人专属招式都进主表） */
  if (DATA.newMoves) {
    Object.keys(DATA.newMoves).forEach(function (k) { DATA.moves[k] = DATA.newMoves[k]; });
  }
  if (DATA.enemyMoves) {
    Object.keys(DATA.enemyMoves).forEach(function (k) { DATA.moves[k] = DATA.enemyMoves[k]; });
  }
  if (DATA.duelExtraMoves) {
    Object.keys(DATA.duelExtraMoves).forEach(function (k) { DATA.moves[k] = DATA.duelExtraMoves[k]; });
  }
  /* 3. 兵装：并入（去重） */
  if (DATA.newWeapons) {
    DATA.newWeapons.forEach(function (w) {
      if (!DATA.weapons.some(function (x) { return x.id === w.id; })) DATA.weapons.push(w);
    });
  }
  /* 4. 兵装 → 招式 映射：并入 */
  if (DATA.newWeaponMoves) {
    Object.keys(DATA.newWeaponMoves).forEach(function (k) { DATA.weaponMoves[k] = DATA.newWeaponMoves[k]; });
  }
  /* 5. 适配度矩阵重算（类型变多了） */
  DATA.affinity = (function () {
    var T = DATA.moveTypes;
    var dot = function (a, b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; };
    var norm = function (a) { return Math.sqrt(dot(a, a)); };
    var out = {};
    Object.keys(T).forEach(function (x) {
      out[x] = {};
      Object.keys(T).forEach(function (y) {
        var v = dot(T[x].vec, T[y].vec) / (norm(T[x].vec) * norm(T[y].vec));
        out[x][y] = Math.max(0, Math.min(1, v));
      });
    });
    return out;
  })();
  /* 6. 每个职业的默认兵装（用于随机生成队友） */
  DATA.jobDefaultWeapon = {
    warrior: "sword_std", mage: "staff_std", healer: "kit_field",
    ranger: "bow_std", gunner: "gun_hand", mechanic: "drone_std"
  };
})();
